spec.query:
import "math"

from(bucket: "gatling")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "gatling" and r["simulation"] == "PerfTestSimulation" and r["_field"] == "count")
  |> filter(fn: (r) => r["status"] =~ /^[0-9]{3}$/)
  |> map(fn: (r) => ({
      r with
      status_type: if r["status"] =~ /^[45][0-9]{2}$/ then "ko" else "ok"
  }))
  |> group(columns: ["_field", "status_type"])
  |> sum(column: "_value")
  |> pivot(rowKey: ["_field"], columnKey: ["status_type"], valueColumn: "_value")
  |> map(fn: (r) => ({
      ok: if exists r.ok then float(v: r.ok) else 0.0,
      ko: if exists r.ko then float(v: r.ko) else 0.0
  }))
  |> map(fn: (r) => ({
      errors: if (r.ok + r.ko) > 0.0
              then math.round(x: r.ko / (r.ok + r.ko) * 100.0 * 100.0) / 100.0
              else 0.0
  }))
  |> keep(columns: ["errors"])
